# Categorize experiments
categories = {
    "obs_only_norm02": [],       # obs_only ε=0.2 (norm02), 6 seeds
    "argmin_baseline": [],        # argmin baseline
    "vla_only_baseline": [],      # VLA-only baseline
    "magnitude_obs_only": [],     # magnitude curve obs_only various ε
    "magnitude_perdof": [],       # magnitude curve perdof various ε
    "scalar_crm": [],             # scalar CRM
    "other_eval": [],             # other evals
}

def extract_seed(exp_id, spec, exp):
    """Extract seed from various locations"""
    # From spec
    if spec.get("seed") is not None:
        return spec["seed"]
    # From command
    cmd = spec.get("command", "")
    m = re.search(r'--seed\s+(\d+)', cmd)
    if m:
        return int(m.group(1))
    # From exp_id
    m = re.search(r'seed(\d+)', exp_id)
    if m:
        return int(m.group(1))
    # From config
    config = spec.get("config", {})
    if isinstance(config, dict) and config.get("seed"):
        return config["seed"]
    return None

def extract_n_rollouts(exp_id, spec, exp):
    """Extract n_rollouts from various locations"""
    cmd = spec.get("command", "")
    m = re.search(r'--n_rollouts\s+(\d+)', cmd)
    if m:
        return int(m.group(1))
    # From spec fields
    if spec.get("n_rollouts"):
        return spec["n_rollouts"]
    # From eval_data
    eval_data = spec.get("eval_data", "")
    m = re.search(r'(\d+)\s*rollouts', eval_data)
    if m:
        return int(m.group(1))
    # From config
    config = spec.get("config", {})
    if isinstance(config, dict) and config.get("n_rollouts"):
        return config["n_rollouts"]
    return None

def extract_total_rollouts(exp):
    """Extract total_rollouts from metrics"""
    metrics = exp.get("metrics", {})
    if isinstance(metrics, dict):
        return metrics.get("total_rollouts")
    return None

def extract_sr(exp):
    """Extract success rate"""
    metrics = exp.get("metrics", {})
    if isinstance(metrics, dict):
        sr = metrics.get("overall_success_rate")
        if sr is not None:
            return sr
        sr = metrics.get("success_rate")
        if sr is not None:
            return sr
    return None

def extract_files(exp_id, spec, exp):
    """Extract file paths"""
    files = []
    cmd = spec.get("command", "")
    m = re.search(r'--output_file\s+(\S+)', cmd)
    if m:
        files.append(m.group(1))
    if spec.get("log_path"):
        files.append(spec["log_path"])
    if spec.get("output_file"):
        files.append(spec["output_file"])
    return list(set(files))

def extract_epsilon(exp_id, spec):
    """Extract epsilon / max_correction_norm"""
    cmd = spec.get("command", "")
    m = re.search(r'--max_correction_norm\s+([\d.]+)', cmd)
    if m:
        return float(m.group(1))
    # from exp_id
    norm_map = {
        "norm003": 0.03, "norm005": 0.05, "norm01": 0.1,
        "norm02": 0.2, "norm05": 0.5, "uncapped": "uncapped"
    }
    for k, v in norm_map.items():
        if k in exp_id:
            return v
    return None

def categorize(exp_id, exp):
    spec = exp.get("spec", {})
    cmd = spec.get("command", "") or ""
    hypothesis = exp.get("hypothesis", "") or ""

    # Only look at eval experiments
    if not exp_id.startswith("eval"):
        return None

    mode = ""
    if "--mode crm_obs_only" in cmd or "crm_obs_only" in cmd or "mode crm_obs_only" in cmd:
        mode = "obs_only"
    elif "--mode crm_perdof" in cmd or "crm_perdof" in cmd or "mode crm_perdof" in cmd:
        mode = "perdof"
    elif "--mode argmin" in cmd or "argmin" in cmd:
        mode = "argmin"
    elif "--mode vla_only" in cmd or "vla_only" in cmd or "vla-only" in exp_id:
        mode = "vla_only"
    elif "--mode crm_scalar" in cmd or "scalar" in exp_id:
        mode = "scalar"

    # Also check exp_id for mode hints
    if "obs-only" in exp_id or "obsonly" in exp_id:
        mode = "obs_only"
    if "perdof" in exp_id:
        mode = "perdof"
    if "argmin" in exp_id:
        mode = "argmin"
    if "vla-only" in exp_id or "vlaonly" in exp_id:
        mode = "vla_only"
    if "scalar" in exp_id:
        mode = "scalar"

    epsilon = extract_epsilon(exp_id, spec)

    # Categorize
    if mode == "argmin":
        return "argmin_baseline"
    elif mode == "vla_only":
        return "vla_only_baseline"
    elif mode == "scalar":
        return "scalar_crm"
    elif mode == "obs_only":
        if epsilon == 0.2 or "norm02" in exp_id:
            # Check if it's part of magnitude curve or main results
            if "magnitude" in exp_id or "mag" in exp_id or "curve" in exp_id:
                return "magnitude_obs_only"
            # If epsilon is exactly 0.2 and has a seed, it could be main results or magnitude curve
            # Main results = 6 seeds with norm02
            return "obs_only_norm02"
        elif epsilon is not None or "uncapped" in exp_id:
            return "magnitude_obs_only"
        else:
            return "obs_only_norm02"  # default obs_only to norm02 category
    elif mode == "perdof":
        if epsilon == 0.2 or "norm02" in exp_id:
            # perdof magnitude curve includes ε=0.2
            return "magnitude_perdof"
        elif epsilon is not None or "uncapped" in exp_id:
            return "magnitude_perdof"
        else:
            return "magnitude_perdof"

    return "other_eval"

# Process all experiments
for exp_id, exp in sorted(experiments.items()):
    if not exp_id.startswith("eval"):
        continue

    spec = exp.get("spec", {})
    cat = categorize(exp_id, exp)
    if cat is None:
        continue

    entry = {
        "exp_id": exp_id,
        "status": exp.get("status"),
        "server": spec.get("server"),
        "seed": extract_seed(exp_id, spec, exp),
        "n_rollouts": extract_n_rollouts(exp_id, spec, exp),
        "total_rollouts": extract_total_rollouts(exp),
        "sr": extract_sr(exp),
        "epsilon": extract_epsilon(exp_id, spec),
        "files": extract_files(exp_id, spec, exp),
        "command": spec.get("command", ""),
        "conclusion": exp.get("conclusion"),
        "hypothesis": exp.get("hypothesis", ""),
    }
    categories[cat].append(entry)

# Print results
def print_category(name, entries, show_epsilon=False):
    print(f"\n{'='*100}")
    print(f"  {name}  ({len(entries)} experiments)")
    print(f"{'='*100}")

    # Sort by seed, then epsilon, then exp_id
    entries.sort(key=lambda e: (e.get("seed") or 999, str(e.get("epsilon") or ""), e["exp_id"]))

    for e in entries:
        flag = ""
        if e["n_rollouts"] == 20:
            flag = " *** n_rollouts=20 ***"
        if e["total_rollouts"] == 200:
            flag += " *** total_rollouts=200 ***"

        eps_str = f"  ε={e['epsilon']}" if show_epsilon and e['epsilon'] is not None else ""
        sr_str = f"  SR={e['sr']}" if e['sr'] is not None else "  SR=N/A"
        seed_str = f"  seed={e['seed']}" if e['seed'] is not None else ""

        print(f"\n  exp_id: {e['exp_id']}")
        print(f"    status={e['status']}  server={e['server']}{seed_str}{eps_str}")
        print(f"    n_rollouts={e['n_rollouts']}  total_rollouts={e['total_rollouts']}{sr_str}")
        print(f"    conclusion={e['conclusion']}{flag}")
        if e['files']:
            print(f"    files: {e['files']}")
        if e['command']:
            # Truncate long commands
            cmd = e['command']
            if len(cmd) > 200:
                cmd = cmd[:200] + "..."
            print(f"    cmd: {cmd}")
        if e['hypothesis']:
            hyp = e['hypothesis'][:150]
            print(f"    hypothesis: {hyp}")

print_category("1. OBS_ONLY ε=0.2 (norm02) — Main Paper Results K=10", categories["obs_only_norm02"], show_epsilon=True)
print_category("2. ARGMIN BASELINE", categories["argmin_baseline"])
print_category("3. VLA-ONLY BASELINE", categories["vla_only_baseline"])
print_category("4. MAGNITUDE CURVE OBS_ONLY — Various ε", categories["magnitude_obs_only"], show_epsilon=True)
print_category("5. MAGNITUDE CURVE PERDOF — Various ε", categories["magnitude_perdof"], show_epsilon=True)
print_category("6. SCALAR CRM", categories["scalar_crm"])
print_category("7. OTHER EVAL (uncategorized)", categories["other_eval"], show_epsilon=True)

# Summary of n_rollouts=20 or total_rollouts=200 flagged experiments
print(f"\n{'='*100}")
print(f"  FLAGGED: n_rollouts=20 or total_rollouts=200")
print(f"{'='*100}")
flagged = []
for cat, entries in categories.items():
    for e in entries:
        if e["n_rollouts"] == 20 or e["total_rollouts"] == 200:
            flagged.append((cat, e))

if flagged:
    for cat, e in flagged:
        print(f"\n  [{cat}] {e['exp_id']}")
        print(f"    n_rollouts={e['n_rollouts']}  total_rollouts={e['total_rollouts']}  seed={e['seed']}  SR={e['sr']}  status={e['status']}")
        if e['command']:
            print(f"    cmd: {e['command'][:200]}")
else:
    print("  None found.")

# Per-category seed coverage summary
print(f"\n{'='*100}")
print(f"  SEED COVERAGE SUMMARY")
print(f"{'='*100}")
for cat_name, display_name in [
    ("obs_only_norm02", "obs_only ε=0.2"),
    ("argmin_baseline", "argmin"),
    ("vla_only_baseline", "vla_only"),
